// openAi v2.3 отдаёт Responses-формат: { output:[{ content:[{ text }] }] }.
// Запасные пути — под другие версии ноды.
function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  if (Array.isArray(j.content)) {
    const part = j.content.find(c => c.text);
    if (part?.text) return part.text;
  }
  return j.message?.content ?? j.content ?? j.text ?? '';
}
const raw = String(extractText($input.first().json) || '').trim();
// Срезаем markdown-фенсы, если модель их всё-таки поставила.
const body = raw.replace(/^```(?:html)?\s*/i, '').replace(/```\s*$/, '').trim();
if (!body) throw new Error('LLM вернул пустой текст');
return [{ json: { body } }];

