// Внешность Рыжа ЗАШИТА тут, LLM даёт только действие — так лис не «плывёт» от поста к посту.
function extractText(j) {
  if (Array.isArray(j.output)) {
    for (const o of j.output) {
      const part = Array.isArray(o.content) && o.content.find(c => c.text);
      if (part?.text) return part.text;
    }
  }
  return j.message?.content ?? j.content ?? j.text ?? '';
}
const scene = String(extractText($input.first().json) || '').trim().replace(/^["']|["']$/g, '');
const CHAR = "athletic anthropomorphic fox, bipedal, big expressive eyes, pointy ears, fluffy tail with white tip, cream muzzle and belly, orange fur #E8763A, fit athletic build, slightly soft belly, wearing green headband #3FBF6F";
const STYLE = "flat vector mascot illustration, thick clean black outlines, soft cel shading, rounded friendly shapes, vibrant, centered, solid dark background #15151a, mobile app sticker, expressive, no text, no letters, square 1:1";
const prompt = `${CHAR}, ${scene || 'standing confidently, paws on hips'}. ${STYLE}`;
return [{ json: { prompt, scene } }];

const RUBRICS = { check: 'Рыж проверяет', price: 'Почём белок', recipe: 'Рецепт Рыжа', guess: 'На глаз', swap: 'Вместо этого', tried: 'Рыж пробует', fox: 'Лис' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const plain = s => String(s ?? '').replace(/<[^>]+>/g, '').replace(/&(lt|gt|amp|quot);/g, '_');
function buildCaption(c) {
  const head = `<b>#${c.post_id}</b> · ${esc(RUBRICS[c.rubric] || c.rubric || '—')} · v${c.version}\n<i>${esc(c.title)}</i>\n\n`;
  const len = plain(c.body).length;
  if (plain(head + c.body).length <= 1024) return { caption: head + c.body, fits: true, len };
  const note = `<b>#${c.post_id}</b> ⚠️ ${len} зн. — длиннее подписи (1024). Ответь «сократи до 800».\n\n`;
  return { caption: note + esc(plain(c.body).slice(0, 850)) + '…', fits: false, len };
}

// Новый черновик приходит после Mark Topic Used, перерисовка — после Load Post (там есть body).
const inp = $input.first().json;
let c;
if (inp.body !== undefined) {
  c = { post_id: inp.id, title: inp.title, rubric: inp.rubric, body: inp.body,
        version: inp.version, old_post_id: inp.old_post_id };
} else {
  const t = $('Topic').first().json;
  c = { post_id: $('Save Draft').first().json.id, title: t.title, rubric: t.rubric,
        body: $('Parse Draft').first().json.body, version: 1, old_post_id: t.old_post_id };
}
return [{ json: { ...c, ...buildCaption(c) } }];

