// Одна и та же картинка каждому редактору — отдельным item (бинарь копируется).
const bin = $input.first().binary;
const eds = $('Editors').first().json.editors || [];
if (!eds.length) throw new Error('ryzh_editors пуст — некому слать черновик');
return eds.map(chat_id => ({ json: { chat_id }, binary: bin }));

